import { cn } from "@/lib/utils";
import { ICON_SPRITE, type IconName } from "./icon-names";

export { ICON_NAMES, type IconName } from "./icon-names";

/**
 * Lucide icons served from one cached SVG sprite (public/icons/sprite.svg,
 * generated by `npm run icons`). Stroke styling lives in the `.icon` class in
 * globals.css, so each icon is a tiny `<svg><use/></svg>` — this keeps pages
 * and their payload small.
 *
 * Content files reference icons by name; an unknown name is a type error.
 */
export function Icon({ name, className, strokeWidth }: { name: IconName; className?: string; strokeWidth?: number }) {
  return (
    <svg aria-hidden="true" className={cn("icon", className)} style={strokeWidth ? { strokeWidth } : undefined}>
      <use href={`${ICON_SPRITE}#${name}`} />
    </svg>
  );
}
